```java
public static int digitSum(int n) {
    int sum = 0;
    while (n > 0) {
        sum += n % 10;
        n /= 10;
    }
    return sum;
}
```

```java
public static int countDivisible(int lo, int hi, int k) {
    int count = 0;
    for (int x = lo; x <= hi; x++) {
        if (digitSum(x) % k == 0) {
            count++;
        }
    }
    return count;
}
```

```java
public class PunchCard {
    private int remaining;
    private int punches;
    public PunchCard(int visits) {
        remaining = visits;
        punches = 0;
    }
    public boolean punch() {
        if (remaining == 0) {
            return false;
        }
        remaining--;
        punches++;
        if (punches % 3 == 0) {
            remaining++;
        }
        return true;
    }
    public int getRemaining() {
        return remaining;
    }
}
```

```java
public int totalTime(String artist) {
    int total = 0;
    for (Song s : songs) {
        if (s.getArtist().equals(artist)) {
            total += s.getSeconds();
        }
    }
    return total;
}
```

```java
public int removeShort(int min) {
    int removed = 0;
    for (int i = songs.size() - 1; i >= 0; i--) {
        if (songs.get(i).getSeconds() < min) {
            songs.remove(i);
            removed++;
        }
    }
    return removed;
}
```

```java
public double testAverage(int c) {
    int sum = 0;
    for (int r = 0; r < scores.length; r++) {
        sum += scores[r][c];
    }
    return (double) sum / scores.length;
}
```

```java
public int mostImproved() {
    int last = scores[0].length - 1;
    int best = 0;
    int bestDiff = scores[0][last] - scores[0][0];
    for (int r = 1; r < scores.length; r++) {
        int diff = scores[r][last] - scores[r][0];
        if (diff > bestDiff) {
            bestDiff = diff;
            best = r;
        }
    }
    return best;
}
```
